package overlay

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"strings"

	"gitlocal/internal/gitexec"
	"gitlocal/internal/storage"
)

// installedCommand accepts only the exact configuration shape generated by
// FilterConfig. A valid Git config file could otherwise replace the required
// process with an unrelated command while leaving the include in place.
func installedCommand(data []byte) (string, string, error) {
	const start = "[filter \"gitlocal-overlay\"]\n\tprocess = "
	const end = "\n\trequired = true\n"
	if !bytes.HasPrefix(data, []byte(start)) || !bytes.HasSuffix(data, []byte(end)) {
		return "", "", errors.New("overlay filter configuration was changed")
	}
	encoded := string(data[len(start) : len(data)-len(end)])
	command, err := configUnquote(encoded)
	if err != nil || !strings.HasSuffix(command, " overlay filter-process") {
		return "", "", errors.New("overlay filter configuration was changed")
	}
	quoted := strings.TrimSuffix(command, " overlay filter-process")
	if len(quoted) < 2 || quoted[0] != '\'' || quoted[len(quoted)-1] != '\'' {
		return "", "", errors.New("overlay filter configuration was changed")
	}
	executable := strings.ReplaceAll(quoted[1:len(quoted)-1], "'\\''", "'")
	want, err := FilterConfig(executable)
	if err != nil || !bytes.Equal(data, want) {
		return "", "", errors.New("overlay filter configuration was changed")
	}
	return executable, command, nil
}

func checkEffectiveFilter(ctx context.Context, r *gitexec.Runner, root, command string) error {
	got, err := effectiveConfig(ctx, r, root, "--get", "filter.gitlocal-overlay.process")
	if err != nil || string(got) != command+"\n" {
		return errors.New("effective overlay filter process differs from the installed command")
	}
	got, err = effectiveConfig(ctx, r, root, "--bool", "--get", "filter.gitlocal-overlay.required")
	if err != nil || string(got) != "true\n" {
		return errors.New("effective overlay filter is not required")
	}
	return nil
}

// AuditResetFilter verifies the only checkout filter that git-local permits
// while it performs an explicit hard reset. It also handles a configured but
// currently unused overlay filter, which AuditInstallation normally skips.
func AuditResetFilter(ctx context.Context, r *gitexec.Runner, cwd, admin, commonPath string) error {
	common, err := storage.OpenDir(commonPath)
	if err != nil {
		return err
	}
	defer common.Close()
	lock, err := common.LockExisting(ctx, "gitlocal/locks/repository.lock")
	if err != nil {
		return err
	}
	defer lock.Close()
	d, err := storage.OpenDir(filepath.Join(commonPath, "gitlocal"))
	if err != nil {
		return err
	}
	defer d.Close()
	includes, err := localIncludes(ctx, r, cwd)
	if err != nil {
		return err
	}
	count, legacy := managedIncludes(includes)
	if len(legacy) > 0 {
		return legacyIncludeError(legacy[0])
	}
	if count != 1 {
		return fmt.Errorf("overlay filter requires exactly one managed include; found %d", count)
	}
	config, exists, _, err := readOptional(d, filterConfigName, 1<<20)
	if err != nil {
		return err
	}
	if !exists {
		return errors.New("overlay filter has no managed configuration file")
	}
	executable, command, err := installedCommand(config)
	if err != nil {
		return err
	}
	if !filterExecutableReady(executable) {
		return fmt.Errorf("overlay filter executable is unavailable: %s", executable)
	}
	effective, err := r.Main(ctx, cwd, admin, "config", "--null", "--list")
	if err != nil {
		return err
	}
	values := map[string]string{}
	for _, record := range bytes.Split(effective, []byte{0}) {
		key, value, ok := strings.Cut(string(record), "\n")
		if ok {
			values[key] = value
		}
	}
	if values["filter.gitlocal-overlay.process"] != command || values["filter.gitlocal-overlay.required"] != "true" {
		return errors.New("effective overlay filter differs from the managed command")
	}
	return nil
}

// AuditInstallation checks the shared filter boundary for every active
// overlay. It reads registration, Git config and attributes without changing
// them, including when invoked by doctor from another worktree.
func AuditInstallation(ctx context.Context, r *gitexec.Runner, cwd, commonPath string) error {
	common, err := storage.OpenDir(commonPath)
	if err != nil {
		return err
	}
	defer common.Close()
	lock, err := common.LockExisting(ctx, "gitlocal/locks/repository.lock")
	if err != nil {
		return err
	}
	defer lock.Close()
	d, err := storage.OpenDir(filepath.Join(commonPath, "gitlocal"))
	if err != nil {
		return err
	}
	defer d.Close()
	paths, _, err := activePathsLocked(d, "", "", "", false)
	if err != nil {
		return err
	}
	if len(paths) == 0 {
		return nil
	}
	attributes, exists, _, err := readOptional(common, "info/attributes", 1<<20)
	if err != nil {
		return err
	}
	if !exists {
		return errors.New("active overlays have no managed Git attributes")
	}
	if _, err := AttributeUserBytes(attributes, paths); err != nil {
		return err
	}
	includes, err := localIncludes(ctx, r, cwd)
	if err != nil {
		return err
	}
	count, legacy := managedIncludes(includes)
	if len(legacy) > 0 {
		return legacyIncludeError(legacy[0])
	}
	if count != 1 {
		return fmt.Errorf("active overlays require exactly one filter include; found %d; run git local overlay remove <name> for each active overlay (saved versions and the working file are kept), then git local overlay add each again", count)
	}
	if exists, err := localRequired(ctx, r, cwd); err != nil {
		return err
	} else if !exists {
		return errors.New("local Git config does not set " + requiredKey + ", so a missing include would fail open; rerun git local overlay add for an active overlay to restore it")
	}
	config, exists, _, err := readOptional(d, filterConfigName, 1<<20)
	if err != nil {
		return err
	}
	if !exists {
		return errors.New("active overlays have no filter configuration file; run git local overlay remove <name> for each active overlay (saved versions and the working file are kept), then git local overlay add each again")
	}
	executable, command, err := installedCommand(config)
	if err != nil {
		return err
	}
	if !filterExecutableReady(executable) {
		return fmt.Errorf("overlay filter executable is unavailable: %s", executable)
	}
	if err := checkEffectiveFilter(ctx, r, cwd, command); err != nil {
		return err
	}
	for _, path := range paths {
		attrs, err := r.CheckAttributes(ctx, cwd, path)
		if err != nil {
			return err
		}
		if attrs["filter"] != "gitlocal-overlay" {
			return fmt.Errorf("overlay path %q no longer uses the required filter", path)
		}
	}
	return nil
}

func legacyIncludeError(include string) error {
	return fmt.Errorf("overlay filter include uses an absolute path that stops resolving when the checkout moves: %s; rerun git local overlay add for an active overlay to migrate it", include)
}

func filterExecutableReady(path string) bool {
	return filterExecutableReadyForOS(path, runtime.GOOS)
}

func filterExecutableReadyForOS(path, goos string) bool {
	info, err := os.Stat(path)
	if err != nil || !info.Mode().IsRegular() {
		return false
	}
	if goos == "windows" {
		return strings.EqualFold(filepath.Ext(path), ".exe")
	}
	return info.Mode().Perm()&0111 != 0
}
